#!/usr/bin/env bash

blacklist_check(){
    # this function is generated by slop
    if awk -F: -v hasher="$hash" '
        NR > 3 {
            value = $2
            gsub(/^[[:space:]]+|[[:space:]]+$/, "", value)
            if (tolower(value) == tolower(hash)) found = 1
        }
        END { exit !found }
        ' BLACKLIST.TXT; then
    ALLOW_UPDATE=false
    echo "GOT BLACKLISTED"
    fi
}

check_version(){
    last_ver="$(cat last_hash.txt)"
    if [ "$hash" = "$last_ver" ]; then
        ALLOW_UPDATE=false
        echo "Same version, skipping update"
    fi
}

# Source - https://stackoverflow.com/a/17744637
# Posted by kenorb, modified by community. See post 'Timeline' for change history
# Retrieved 2026-10-21, License - CC BY-SA 4.0
dir="$(cd -P -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"
cd $dir


curl -o Acheron.zip -L "https://nightly.link/ouwou/acheron/workflows/build/master/acheron-appimage.zip"
curl -o BLACKLIST.TXT -L "https://raw.githubusercontent.com/Zen-Fyre/Acheron-Auto-Update-Script/main/sha256-blacklist"
hash=sha256:"$(sha256sum Acheron.zip | awk '{print $1}')"
ALLOW_UPDATE=true


# ALLOW_UPDATE set to false based on the checks
blacklist_check
check_version


if [ "$ALLOW_UPDATE" = true ]; then
    printf '%s\n' "$hash" > last_hash.txt
    7z -y x Acheron.zip
fi



./Acheron-x86_64.AppImage &
exit
